SELECT id, method, ROW_NUMBER() OVER w_hist AS row_seq, LEAD(amount, 1) OVER (PARTITION BY status, method ORDER BY amount, id) AS next_amount, SUM(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, COUNT(amount) OVER (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_count_30d FROM payments WINDOW w_hist AS (ORDER BY paid_at DESC, id);
